SECTION_NAMES=['Research Question','Pre-experiment Hypothesis','Experiment Design','Actual Execution','Raw Results','Interpretation','Scientific Contribution','Limitations and Alternative Explanations','Decision','Reproduction']
def report(name,values):
    text='# '+name+'\n\n'
    for j,(title,value) in enumerate(zip(SECTION_NAMES,values),1):text+=f'## {j}. {title}\n\n{value}\n\n'
    (ROOT/'reports'/name).write_text(text,encoding='utf-8')
def all_metrics():return [json.loads(p.read_text()) for p in (ROOT/'runs').glob('*/metrics.json')]
def table(rows):
    if not rows:return 'No completed result. Explicit statuses are recorded in EXPERIMENT_MATRIX.csv.'
    cols=['run_id','dataset','horizon','variant','k','seed','validation_mae','reproduced_mse','reproduced_mae','num_parameters','train_seconds']
    return pd.DataFrame(rows)[[c for c in cols if c in rows[0]]].to_markdown(index=False)
def comparison_text(rows):
    lines=[];allm=all_metrics();reference=pd.read_csv(ROOT/'results/stage0_baseline_verification.csv')
    for r in sorted(rows,key=lambda x:(x['dataset'],x['horizon'],x['variant'],x['k'])):
        if r['seed']!=2021:continue
        b=next((x for x in allm if x['dataset']==r['dataset'] and x['horizon']==r['horizon'] and x['variant']=='B0' and x['seed']==2021),None)
        old=reference[(reference.dataset==r['dataset'])&(reference.horizon==r['horizon'])].iloc[0]
        if b:lines.append(f"{r['run_id']}: relative test MSE gain versus equally continued B0={1-r['reproduced_mse']/b['reproduced_mse']:.2%}, MAE gain={1-r['reproduced_mae']/b['reproduced_mae']:.2%}; versus verified original checkpoint MSE gain={1-r['reproduced_mse']/old.mse:.2%}. Validation MAE={r['validation_mae']:.6f}; best Stage1 epoch={r['stage1_best_epoch']}/{r['stage1_epochs']}, Stage2={r['best_epoch']}/{r['stage2_epochs']}.")
    return '\n\n'.join(lines)
def contribution_text(stage,rows):
    if stage==2:
        return 'One-shot attention improves both test metrics over continued B0 on both tasks, but every one-shot attention/convolution fit remains worse than the independently verified original checkpoint in test MSE. Conv and attention have closely matched parameter counts and show no consistent attention-specific advantage across both metrics. The largest relative gains over continued B0 occur in the first120 forecast positions, rather than uniquely in the most distant band. This comparison excludes a simple extra-training-budget explanation for the within-continuation point gains; it does not establish that the original local support is the principal real-data bottleneck, or that recurrence is necessary. Single-seed and continuation limitations remain.'
    if stage==3:
        return 'The completed historical-loop, unshared-stack, wider-one-shot and shared-K2/K4 comparisons constrain generic depth, sharing and capacity explanations. Same-checkpoint K1/2/4 results separately test iteration effects without new training. The direct judgments and measured budget table above identify which point comparisons favor recurrence. A single global attention application already removes the structural reach limit; any extra K gain concerns refinement/optimization, rather than uniquely accessing distant conditions. The unshared zero-initialized stack has delayed early-layer gradients, so its score alone cannot exclude optimization differences.'
    return 'The anchored/no-anchor and correction/full-state pairs change one update choice while keeping width and K fixed. Their measured MSE/MAE differences above test whether either design choice improves this continuation setup. Parameter sharing is evaluated alongside C3 and wider controls. The short/long and covariate-quality tables delimit the observed scope; stable norms or nonzero distant sensitivity alone do not count as forecasting success. Masking/noise are sensitivity probes, not causal evidence.'

