    if stage>=4 and (ROOT/'results/stage4_robustness.csv').is_file():
        quality=pd.read_csv(ROOT/'results/stage4_robustness.csv');trajectory=pd.read_csv(ROOT/'results/stage4_trajectory.csv');sensitivity=pd.read_csv(ROOT/'results/stage4_response_sensitivity.csv')
        alternatives=[]
        for ds in ['NP','PJM']:
            rr=[r for r in allm if r['dataset']==ds and r['horizon']==360 and r['seed']==2021]
            non=min([r for r in rr if r['variant'] in ['B0','B1','B2','C3','C4']],key=lambda r:r['validation_mae'])
            for r in [r for r in rr if r['variant']=='NOANCHOR']:
                alternatives.append({'dataset':ds,'ablation':r['run_id'],'validation_selected_control':non['run_id'],'validation_mae_gain':1-r['validation_mae']/non['validation_mae'],'test_mse_gain':1-r['reproduced_mse']/non['reproduced_mse'],'test_mae_gain':1-r['reproduced_mae']/non['reproduced_mae']})
        if alternatives:text+='\n\nPreregistered no-anchor alternative versus the primary control:\n\n'+pd.DataFrame(alternatives).to_markdown(index=False)+'\n\nThese fixed ablations can identify a competing update rule even when the anchored hypothesis is unsupported. A favorable single-seed test difference does not replace the frozen primary C5 comparison or its validation-only expansion gate. Confirming a new primary no-anchor hypothesis would require a new prospective selection and independent validation protocol.'
        text+='\n\nFuture-covariate evaluation sensitivity:\n\n'+quality.to_markdown(index=False)+'\n\nPer-iteration validation diagnostics:\n\n'+trajectory[trajectory.variant.isin(['C5','FULL','NOANCHOR','C3'])].to_markdown(index=False)+'\n\nResponse outside the original decoder support:\n\n'+sensitivity.to_markdown(index=False)
        text+='\n\nNonzero off-window sensitivity confirms that a learned cross-time pathway is used; it does not establish that this pathway improves prediction. Finite stable norm sequences alone do not prove forecasting value. Quality changes are robustness probes with unchanged weights, not retrained ablations or causal interventions.'
    if (ROOT/'results/model_costs.csv').is_file():text+='\n\nMeasured costs:\n\n'+pd.read_csv(ROOT/'results/model_costs.csv').query('seed ==2021').to_markdown(index=False)
