def basic_stage(stage):
    m=all_metrics();plan=json.loads((ROOT/'configs/preregistration.json').read_text());ids={r['run_id'] for r in plan['experiments'] if r['stage']==stage};rows=[r for r in m if r['run_id'] in ids]
    if stage==3:rows+=[r for r in m if r['horizon']==360 and r['variant'] in ['B0','B1','B2'] and r['seed']==2021]
    name={2:'STAGE2_ONESHOT_FUSION.md',3:'STAGE3_RECURRENT_PROPAGATION.md',4:'STAGE4_MECHANISM_AND_GENERALIZATION.md'}[stage]
    file={2:'stage2_comparison.csv',3:'stage3_controls.csv',4:'stage4_ablation.csv'}[stage];write_csv(ROOT/'results'/file,[{k:v for k,v in r.items() if not isinstance(v,(dict,list))} for r in rows])
    report(name,[{2:'Does one-shot future temporal attention or wide convolution improve forecasting over equal-budget continued WorldTS?',3:'Does shared anchored recurrence improve beyond ordinary historical looping, one-shot mixing, unshared stacks and wider one-shot controls?',4:'Are anchoring, correction-only propagation, shared parameters, covariate quality and horizon responsible for any observed effect?'}[stage],'No improvement is presumed. Validation MAE selects checkpoints; all fixed methods and K values were preregistered before new test results.','Same task-specific pretrained seed2021 initialization for every method; continuation seed2021; original complete two-stage objective and maximum20/20epochs, patience5, batch32 and published LR. Shared attention uses Values only from correction, no output bias, eta=sigmoid(logit) initially.5, zero output projection, bidirectional known-future mixing. Conv has nine bidirectional dilated layers, receptive field1023. C3 uses four unshared blocks; C4 uses width128 once. Parameters and actual latency are measured separately.','Completed configurations below. B1 is mathematically identical to shared K1 and is reused as the K1 control, never falsely labeled separate training. Old baseline inference is kept separate from equally budgeted B0 continued training.',table(rows),mechanism_text(stage,rows)+'\n\nA lower test value is not a reason to change the architecture or gate. Whole-model parameter and actual latency mismatches limit efficiency claims. No result is attributed to sharing before the appropriate controls are compared.',contribution_text(stage,rows),'Main family is checkpoint-initialized continuation, not from-scratch. Each continuation seed starts from the same original trained weights. Fixed-K decoders may mismatch states at other test depths. Masking/noise ablations are evaluation robustness tests, not causal interventions.','Proceed to the next minimum stage regardless of sign. Expand seeds only through the preregistered validation gate.','python scripts/train.py --run-id <preregisteredID>; python scripts/orchestrate.py. Per-run research_spec/config/command/history/freeze audit/checkpoint/predictions and numbered stdout attempts are saved.'])
    if rows:
        fig,axes=plt.subplots(1,2,figsize=(11,4))
        for ax,ds in zip(axes,['NP','PJM']):
            rr=[r for r in rows if r['dataset']==ds];ax.bar(np.arange(len(rr)),[r['reproduced_mse'] for r in rr]);ax.set_xticks(np.arange(len(rr)),[f"{r['variant']}K{r['k']}H{r['horizon']}" for r in rr],rotation=60,ha='right');ax.set(title=ds,ylabel='Test MSE')
        fig.tight_layout();filename={2:'stage2_forecasting_comparison.png',3:'stage3_controls_preview.png',4:'stage4_ablation.png'}[stage];fig.savefig(ROOT/'figures'/filename,dpi=160);plt.close(fig)
def block_ci(diff,length,repetitions=2000):
    gen=np.random.default_rng(9281);n=len(diff);assert 0<length<=n;full,remainder=divmod(n,length);sums=np.concatenate([[0.],np.cumsum(diff,dtype='float64')]);starts=gen.integers(0,n-length+1,size=(repetitions,full));total=(sums[starts+length]-sums[starts]).sum(1)
    if remainder:
        last=gen.integers(0,n-length+1,size=repetitions);total+=sums[last+remainder]-sums[last]
    return np.quantile(total/n,[.025,.975]).tolist()
def final_stage():
    plan=json.loads((ROOT/'configs/preregistration.json').read_text());planned_ids={r['run_id'] for r in plan['experiments']};matrix=[r for r in pd.read_csv(ROOT/'EXPERIMENT_MATRIX.csv').to_dict('records') if r['run_id'] in planned_ids]
    for row in matrix:row['optional']=str(row['optional']).lower()=='true'
    assert len(matrix)==len(plan['experiments']);assert all(r['status'] in ['COMPLETE','NOT_RUN'] for r in matrix);assert all(r['status']=='COMPLETE' for r in matrix if not r['optional'])
