    integrity=json.loads((ROOT/'results/independent_verification.json').read_text());assert integrity['all_passed'] and len(integrity['results'])==len(all_metrics());assert json.loads((ROOT/'results/stage1_complete.json').read_text())['passed']
    for stage in [2,3,4]:basic_stage(stage)
    m=all_metrics();decision=json.loads((ROOT/'results/validation_expansion_decision.json').read_text());cost=pd.read_csv(ROOT/'results/model_costs.csv');depth=pd.read_csv(ROOT/'results/stage3_loop_depth.csv');pairs=[];bootstrap=[];direction=[];budget=[];original_comparisons=[]
    reference=pd.read_csv(ROOT/'results/stage0_baseline_verification.csv')
    for sel in decision['selection']:
        ds=sel['dataset'];chosen_non=next(x for x in m if x['run_id']==sel['nonrecurrent']);chosen_loop=next(x for x in m if x['run_id']==sel['shared_loop']);nn=chosen_non['variant'];lk=chosen_loop['k']
        seeds=[2021,2022,2023] if decision['expand_three_seed'] else [2021]
        for s in seeds:
            non=next(x for x in m if x['dataset']==ds and x['horizon']==360 and x['seed']==s and x['variant']==nn);loop=next(x for x in m if x['dataset']==ds and x['horizon']==360 and x['seed']==s and x['variant']=='C5' and x['k']==lk)
            a=np.load(ROOT/'runs'/non['run_id']/'predictions.npz');b=np.load(ROOT/'runs'/loop['run_id']/'predictions.npz');assert np.array_equal(a['origins'],b['origins']) and np.array_equal(a['true'],b['true'])
            da=(a['pred'].astype('float64')-a['true'])**2;db=(b['pred'].astype('float64')-b['true'])**2;d=(db-da).mean((1,2));gain=1-loop['reproduced_mse']/non['reproduced_mse'];maegain=1-loop['reproduced_mae']/non['reproduced_mae'];pairs.append({'dataset':ds,'seed':s,'nonrecurrent':non['run_id'],'shared_loop':loop['run_id'],'relative_mse_gain':gain,'relative_mae_gain':maegain,'mse_difference_loop_minus_control':float(d.mean())})
            for length in [360,720,1680]:lo,hi=block_ci(d,length);bootstrap.append({'dataset':ds,'seed':s,'block_length_origins':length,'mean_mse_difference':float(d.mean()),'ci95_low':lo,'ci95_high':hi,'bootstrap_repetitions':2000,'overlap_note':'Contiguous rolling-origin blocks; horizon360 overlaps handled, sensitivity to block length reported'})
            cp=cost[cost.run_id==non['run_id']].iloc[0];cl=cost[cost.run_id==loop['run_id']].iloc[0];budget.append({'dataset':ds,'seed':s,'parameter_relative_diff':float(cl.parameters/cp.parameters-1),'batch32_latency_relative_diff':float(cl.batch32_ms_median/cp.batch32_ms_median-1),'within_parameter_10pct':bool(abs(cl.parameters/cp.parameters-1)<=.10),'within_latency_25pct':bool(abs(cl.batch32_ms_median/cp.batch32_ms_median-1)<=.25)})
            old=reference[(reference.dataset==ds)&(reference.horizon==360)].iloc[0];original_comparisons.append({'dataset':ds,'seed':s,'shared_loop':loop['run_id'],'mse_gain_vs_verified_original':1-loop['reproduced_mse']/old.mse,'mae_gain_vs_verified_original':1-loop['reproduced_mae']/old.mae,'scope':'verified original checkpoint, no added continuation budget; reference, separate from matched training control'})
        direction.append({'dataset':ds,'mse_gain_mean':float(np.mean([p['relative_mse_gain'] for p in pairs if p['dataset']==ds])),'mae_gain_mean':float(np.mean([p['relative_mae_gain'] for p in pairs if p['dataset']==ds]))})
    gains=[d['mse_gain_mean'] for d in direction];positive_all=all(p['relative_mse_gain']>0 and p['relative_mae_gain']>=0 for p in pairs);depthg=[]
    selected_loop_ids={r['shared_loop'] for r in pairs}
    for rid,g in depth.groupby('run_id'):
        if rid in selected_loop_ids and g.horizon.iloc[0]==360:depthg.append(1-float(g[g.test_k==4].mse.iloc[0])/float(g[g.test_k==1].mse.iloc[0]))
    matched=all(x['within_parameter_10pct'] and x['within_latency_25pct'] for x in budget)
    significant=all(r['ci95_high']<0 for r in bootstrap)
    original_improved=all(r['mse_gain_vs_verified_original']>0 and r['mae_gain_vs_verified_original']>=0 for r in original_comparisons)
