def plots(m,cost,depth):
    fig,axes=plt.subplots(1,2,figsize=(10,4))
    for ax,ds in zip(axes,['NP','PJM']):
        for rid,g in depth[(depth.dataset==ds)&(depth.horizon==360)&(depth.seed==2021)].groupby('run_id'):ax.plot(g.test_k,g.mse,'o-',label=rid)
        ax.set(title=ds,xlabel='Test-time iterations, same checkpoint',ylabel='Test MSE');ax.legend(fontsize=6)
    fig.tight_layout();fig.savefig(ROOT/'figures/stage3_depth_vs_error.png',dpi=170);plt.close(fig)
    fig,axes=plt.subplots(1,2,figsize=(12,5))
    for ax,ds in zip(axes,['NP','PJM']):
        for r in m:
            if r['dataset']!=ds or r['horizon']!=360 or r['seed']!=2021:continue
            c=cost[cost.run_id==r['run_id']].iloc[0];ax.scatter(c.batch32_ms_median,r['reproduced_mse'])
            offsets={('NP','C3',4):(-26,-12),('NP','FULL',4):(6,8),('NP','B2',1):(3,-12),('PJM','B2',1):(-2,8),('PJM','C5',4):(6,-12)}
            ax.annotate(r['variant']+'K'+str(r['k']),(c.batch32_ms_median,r['reproduced_mse']),xytext=offsets.get((ds,r['variant'],r['k']),(0,0)),textcoords='offset points',fontsize=7)
        ax.set(title=ds+' 720 to 360; seed2021',xlabel='Measured batch32 GPU latency (ms)',ylabel='Test MSE')
    fig.tight_layout();fig.savefig(ROOT/'figures/stage3_cost_vs_error.png',dpi=170);plt.close(fig)
    t=pd.read_csv(ROOT/'results/stage4_trajectory.csv');fig,axes=plt.subplots(2,2,figsize=(11,8))
    for row,ds in zip(axes,['NP','PJM']):
        for rid,g in t[(t.dataset==ds)&(t.horizon==360)&(t.variant=='C5')].groupby('run_id'):
            row[0].plot(g.iteration,g.delta_rms,'o-',label=rid);row[1].plot(g.iteration,g.validation_sample_mse,'o-',label=rid)
        row[0].set(title=ds,xlabel='Iteration',ylabel='Correction RMS');row[1].set(title=ds,xlabel='Iteration',ylabel='Validation sample MSE');row[0].legend(fontsize=6)
    fig.suptitle('32 fixed validation origins; fixed checkpoint and decoder')
    fig.tight_layout();fig.savefig(ROOT/'figures/stage4_trajectory_diagnostics.png',dpi=170);plt.close(fig)
